pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 credChainId, uint256 credId) public {
        vm.assume(credChainId > 0);
        vm.assume(credId > 0);

        // initialize() calls back into the factory (msg.sender) to read
        // protocolFeeDestination(), so a contract helper is required.
        Factory factory = new Factory();
        vm.prank(address(factory));
        c.initialize(credChainId, credId, "v", address(factory));

        // General rule: the stored owner is never the zero address after
        // initialization (initial owner is the initializing factory address).
        assertTrue(c.owner() != address(0));
    }
}

contract Factory {
    function protocolFeeDestination() external pure returns (address) {
        return address(this);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeFactory factory;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 chainId_, uint256 credId_, string memory vType_, address newOwner) public {
        // keep params in the admissible domain (wide)
        vm.assume(newOwner != address(0));
        vm.assume(bytes(vType_).length < 100);

        // adversarial counterparty: initialize() must be called by a contract acting as the
        // PhiFactory (it sets phiFactoryContract = msg.sender and queries protocolFeeDestination())
        factory = new FakeFactory(address(this));

        // initialize from the fake factory: msg.sender (the factory) becomes the stored owner
        vm.prank(address(factory));
        c.initialize(chainId_, credId_, vType_, address(factory));

        // the CURRENT owner initiates a two-step ownership transfer to ANY nonzero newOwner
        vm.prank(address(factory));
        c.transferOwnership(newOwner);

        // the fuzzed newOwner accepts
        vm.prank(newOwner);
        c.acceptOwnership();

        // GENERAL RULE: for every admissible newOwner, the completed two-step transfer makes
        // the reported owner equal the accepting newOwner (a real, stored, nonzero owner).
        assertTrue(c.owner() == newOwner);
    }
}

// minimal adversarial helper embodying the PhiFactory counterparty required by initialize()
contract FakeFactory {
    address public protocolFeeDestination;

    constructor(address dest) {
        protocolFeeDestination = dest;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IPhiFactoryLike {
    function protocolFeeDestination() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    Factory factory;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 credId, address feeDest, string memory verifType) public {
        vm.assume(feeDest != address(0));
        vm.assume(bytes(verifType).length < 100);
        factory = new Factory(feeDest);
        // initialize must succeed when driven by a factory whose protocolFeeDestination() is non-zero
        factory.doInitialize(c, uint256(1) + (credId % type(uint64).max), verifType);
        // General rule: after successful initialization, the stored owner (the initializing factory) is non-zero
        assertTrue(c.owner() == address(factory) && c.owner() != address(0));
    }
}

contract Factory {
    address public protocolFeeDestination;

    constructor(address feeDest) {
        protocolFeeDestination = feeDest;
    }

    function doInitialize(C target, uint256 credId, string memory verifType) external {
        target.initialize(1, credId, verifType, protocolFeeDestination);
    }

    function phiRewardsAddress() external pure returns (address) {
        return address(this);
    }

    receive() external payable {}
}
